from fast_rub import filters

# فیلتر ساده
@bot.on_message(filters.text("/start"))

# ترکیب با &
@bot.on_message(filters.text("/admin") & filters.is_user)

# ترکیب با |
@bot.on_message(filters.text("/help") | filters.text("راهنما"))

# ترکیب با ~ (NOT)
@bot.on_message(~filters.is_group)  # فقط PV

# Async — چک کردن دیتابیس
@bot.on_message(filters.db_exists("users", lambda u: {"chat_id": u.chat_id}, db=my_db))

# اعتبارسنجی
@bot.on_message(filters.validate(is_digit=True, min_length=5))

# ساخت فیلتر سفارشی
class CustomFilter(filters.Filter):
    def __call__(self, update):
        return "سلام" in update.text

@bot.on_message(CustomFilter())

from fast_rub.types import errors

try:
    await bot.send_message("invalid_chat_id", "سلام")
except errors.ServerRubikaError:
    print("❌ سرور روبیکا پاسخ نداد.")
except errors.TokenInvalid:
    print("❌ توکن نامعتبر است.")
except errors.InvalidID:
    print("❌ شناسه نامعتبر است.")
